#include <iostream>
class Base {
public:    int x = 1;
protected: int y = 2;
private:   int z = 3;   // 派生类不可访问
};
class Derived : public Base {
public:
    int getX() const { return x; }
    int getY() const { return y; }
    int sum() const { return x + y; }   // OK：public/protected 可见，private(z) 不可见
};
int main() {
    Derived d;
    std::cout << d.getX() << ' ' << d.getY() << ' ' << d.sum();
}
